1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  body { font-family: system-ui, sans-serif; max-width: 32rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
9	  h1 { font-size: 1.5rem; }
10	  form { display: flex; gap: .5rem; }
11	  form input { flex: 1; padding: .5rem; font-size: 1rem; }
12	  form input[type="date"] { flex: 0 0 auto; }
13	  button { padding: .5rem .75rem; font-size: 1rem; cursor: pointer; }
14	  ul { list-style: none; padding: 0; margin-top: 1rem; }
15	  li { display: flex; align-items: center; gap: .5rem; padding: .5rem 0; border-bottom: 1px solid #ddd; }
16	  li span { flex: 1; overflow-wrap: anywhere; }
17	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
18	  li time { font-size: .875rem; color: #555; white-space: nowrap; }
19	  li[data-overdue="true"] { background: #fdecea; }
20	  li[data-overdue="true"] time { color: #b00020; font-weight: 600; }
21	  .filters { display: flex; gap: .5rem; margin-top: 1rem; }
22	  .filters button[aria-pressed="true"] { font-weight: 600; }
23	  .search { display: block; width: 100%; box-sizing: border-box; margin-top: 1rem; padding: .5rem; font-size: 1rem; }
24	  li input[data-testid="todo-edit"] { flex: 1; min-width: 0; padding: .25rem; font: inherit; }
25	</style>
26	</head>
27	<body>
28	<h1>Todos</h1>
29	<form id="add-form">
30	  <input data-testid="todo-input" type="text" placeholder="What needs doing?" autocomplete="off">
31	  <input data-testid="todo-due" type="date" aria-label="Due date">
32	  <select data-testid="todo-priority" aria-label="Priority">
33	    <option value="low">Low</option>
34	    <option value="med" selected>Med</option>
35	    <option value="high">High</option>
36	  </select>
37	  <button data-testid="todo-add" type="submit">Add</button>
38	</form>
39	<input class="search" data-testid="search-input" type="search" placeholder="Search" aria-label="Search todos" autocomplete="off">
40	<div class="filters">
41	  <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
42	  <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
43	  <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
44	</div>
45	<ul data-testid="todo-list"></ul>
46	<script>
47	(function () {
48	  var KEY = 'todos';
49	  var input = document.querySelector('[data-testid="todo-input"]');
50	  var dueInput = document.querySelector('[data-testid="todo-due"]');
51	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
52	  var list = document.querySelector('[data-testid="todo-list"]');
53	  var form = document.getElementById('add-form');
54	  var filterButtons = document.querySelectorAll('[data-filter]');
55	  var searchInput = document.querySelector('[data-testid="search-input"]');
56	  var filter = 'all';
57	  var search = '';
58	  var editing = false;
59	
60	  function load() {
61	    try {
62	      var data = JSON.parse(localStorage.getItem(KEY));
63	      return Array.isArray(data) ? data : [];
64	    } catch (e) {
65	      return [];
66	    }
67	  }
68	
69	  function save() {
70	    try { localStorage.setItem(KEY, JSON.stringify(todos)); } catch (e) {}
71	  }
72	
73	  function newId() {
74	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
75	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
76	  }
77	
78	  // Project rule: due dates are plain YYYY-MM-DD strings, read as LOCAL calendar dates.
79	  // Never parse them through Date/UTC. Overdue = due date strictly before today's local date.
80	  function validDue(value) {
81	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
82	  }
83	
84	  function pad(n) { return (n < 10 ? '0' : '') + n; }
85	
86	  function localToday(now) {
87	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
88	  }
89	
90	  // Zero-padded YYYY-MM-DD strings sort lexicographically in date order.
91	  function isOverdue(due, today) {
92	    return !!validDue(due) && due < today;
93	  }
94	
95	  // Project rule: priority is low|med|high; anything else (including missing) is med.
96	  function validPriority(value) {
97	    return value === 'low' || value === 'high' ? value : 'med';
98	  }
99	
100	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
101	
102	  // Project rule: priority order high, med, low; insertion order within the same priority.
103	  // Stable sort keeps insertion order for ties.
104	  function byPriority(list) {
105	    return list
106	      .map(function (t, i) { return { t: t, i: i }; })
107	      .sort(function (a, b) {
108	        return (PRIORITY_RANK[validPriority(a.t.priority)] - PRIORITY_RANK[validPriority(b.t.priority)]) || (a.i - b.i);
109	      })
110	      .map(function (x) { return x.t; });
111	  }
112	
113	  // Search: case-insensitive substring on text; applied on top of the status filter.
114	  function matchesSearch(todo, term) {
115	    return !term || String(todo.text).toLowerCase().indexOf(term.toLowerCase()) !== -1;
116	  }
117	
118	  // Project rule: active todos first, completed below; within each group, sorted by priority.
119	  function visibleTodos(all, f, term) {
120	    all = all.filter(function (t) { return matchesSearch(t, term); });
121	    var active = byPriority(all.filter(function (t) { return !t.completed; }));
122	    var done = byPriority(all.filter(function (t) { return !!t.completed; }));
123	    if (f === 'active') return active;
124	    if (f === 'completed') return done;
125	    return active.concat(done);
126	  }
127	
128	  function render() {
129	    list.textContent = '';
130	    renderedDay = localToday(new Date());
131	    filterButtons.forEach(function (b) {
132	      b.setAttribute('aria-pressed', String(b.dataset.filter === filter));
133	    });
134	    visibleTodos(todos, filter, search).forEach(function (todo) {
135	      var li = document.createElement('li');
136	      li.setAttribute('data-testid', 'todo-item');
137	      li.setAttribute('data-completed', String(!!todo.completed));
138	      li.setAttribute('data-overdue', String(isOverdue(todo.due, renderedDay)));
139	      li.setAttribute('data-priority', validPriority(todo.priority));
140	      li.dataset.id = todo.id;
141	
142	      var toggle = document.createElement('input');
143	      toggle.setAttribute('data-testid', 'todo-toggle');
144	      toggle.type = 'checkbox';
145	      toggle.checked = !!todo.completed;
146	      toggle.setAttribute('aria-label', 'Mark complete');
147	      toggle.addEventListener('change', function () {
148	        todo.completed = toggle.checked;
149	        save();
150	        render();
151	      });
152	
153	      var text = document.createElement('span');
154	      text.setAttribute('data-testid', 'todo-text');
155	      text.textContent = todo.text;
156	      text.addEventListener('dblclick', function () { startEdit(todo, text); });
157	
158	      var del = document.createElement('button');
159	      del.setAttribute('data-testid', 'todo-delete');
160	      del.type = 'button';
161	      del.textContent = 'Delete';
162	      del.addEventListener('click', function () {
163	        todos = todos.filter(function (t) { return t.id !== todo.id; });
164	        save();
165	        render();
166	      });
167	
168	      li.appendChild(toggle);
169	      li.appendChild(text);
170	      if (validDue(todo.due)) {
171	        var due = document.createElement('time');
172	        due.setAttribute('data-testid', 'todo-due-date');
173	        due.dateTime = todo.due;
174	        due.textContent = 'Due ' + todo.due;
175	        li.appendChild(due);
176	      }
177	      li.appendChild(del);
178	      list.appendChild(li);
179	    });
180	  }
181	
182	  // Enter and blur commit, Escape cancels. Empty text keeps the original.
183	  function startEdit(todo, span) {
184	    var field = document.createElement('input');
185	    field.type = 'text';
186	    field.setAttribute('data-testid', 'todo-edit');
187	    field.setAttribute('aria-label', 'Edit todo');
188	    field.value = todo.text;
189	    var finished = false;
190	    editing = true;
191	
192	    function finish(commit) {
193	      if (finished) return;
194	      finished = true;
195	      editing = false;
196	      var value = field.value.trim();
197	      if (commit && value) {
198	        todo.text = value;
199	        save();
200	      }
201	      render();
202	    }
203	
204	    field.addEventListener('keydown', function (e) {
205	      if (e.key === 'Enter') { e.preventDefault(); finish(true); }
206	      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
207	    });
208	    field.addEventListener('blur', function () { finish(true); });
209	
210	    span.replaceWith(field);
211	    field.focus();
212	    field.select();
213	  }
214	
215	  var todos = load();
216	  var renderedDay = '';
217	
218	  form.addEventListener('submit', function (e) {
219	    e.preventDefault();
220	    var text = input.value.trim();
221	    if (!text) return;
222	    todos.push({ id: newId(), text: text, completed: false, createdAt: Date.now(), due: validDue(dueInput.value), priority: validPriority(priorityInput.value) });
223	    save();
224	    render();
225	    input.value = '';
226	    dueInput.value = '';
227	    priorityInput.value = 'med';
228	    input.focus();
229	  });
230	
231	  searchInput.addEventListener('input', function () {
232	    search = searchInput.value;
233	    render();
234	  });
235	
236	  filterButtons.forEach(function (b) {
237	    b.addEventListener('click', function () {
238	      filter = b.dataset.filter;
239	      render();
240	    });
241	  });
242	
243	  // Re-render when the local calendar day changes so overdue flags stay current.
244	  setInterval(function () {
245	    if (!editing && localToday(new Date()) !== renderedDay) render();
246	  }, 60000);
247	
248	  render();
249	})();
250	</script>
251	</body>
252	</html>
